import{_ as a,o as n,c as i,a3 as l}from"./chunks/framework.MGD2uYU7.js";const r=JSON.parse('{"title":"SC-26 — Gói của tôi","description":"","frontmatter":{"title":"SC-26 — Gói của tôi"},"headers":[],"relativePath":"wireframes/user/sc-26-goi-cua-toi.md","filePath":"wireframes/user/sc-26-goi-cua-toi.md","lastUpdated":1791606799000}'),t={name:"wireframes/user/sc-26-goi-cua-toi.md"};function c(p,s,d,e,h,o){return n(),i("div",null,[...s[0]||(s[0]=[l('<h1 id="sc-26-—-goi-cua-toi-subscription" tabindex="-1">SC-26 — Gói của tôi (subscription) <a class="header-anchor" href="#sc-26-—-goi-cua-toi-subscription" aria-label="Permalink to &quot;SC-26 — Gói của tôi (subscription)&quot;">​</a></h1><p><span class="wf-badge muted">ƯU TIÊN THẤP</span> <span class="wf-badge info">Route: /goi-cua-toi</span> <span class="wf-badge muted">Nguồn: docs/05 §3 SC-26 · docs/03 UC-10 · docs/08 BR-PKG-01..06 · docs/02 FR-PKG-01..04 · docs/06 §4.9</span></p><p><strong>Ai xem màn này</strong>: Chủ nhà đang ở gói FREE muốn đăng thêm tin (đây là màn upsell chính, vào từ modal quota ở SC-22) · người đang VIP muốn gia hạn/đổi gói · người vừa hết hạn quay lại xem vì sao badge VIP biến mất. <strong>Cảm xúc cần thiết kế</strong>: &quot;rõ ràng, không bị gài&quot;. Người dùng phải thấy ngay hạn mức còn bao nhiêu, hết hạn ngày nào, và <strong>đổi gói thì mất phần còn lại</strong> — nói trước khi thu tiền, không nói sau. Đây là màn bán hàng nên dễ bị làm quá; giữ trung thực, không đếm ngược giả, không &quot;chỉ còn 2 suất&quot;. <strong>Ví dụ số dùng trong bản vẽ</strong>: gói hiện tại <code>VIP_STANDARD</code> · đăng ký <code>sub_01J9ZK4C6D</code> · mua 10/10/2026 14:32 · hết hạn <code>09/11/2026 14:32 (GMT+7)</code> · còn 21 ngày · đã dùng <code>3/10 tin</code>. Ba gói: FREE <code>0 ₫ / 2 tin</code> · VIP_STANDARD <code>500.000 ₫ / 30 ngày / 10 tin</code> · VIP_PRO <code>1.500.000 ₫ / 30 ngày / 50 tin</code>.</p><h2 id="_1-desktop-—-goi-hien-tai-ba-the-goi" tabindex="-1">1. Desktop — gói hiện tại + ba thẻ gói <a class="header-anchor" href="#_1-desktop-—-goi-hien-tai-ba-the-goi" aria-label="Permalink to &quot;1. Desktop — gói hiện tại + ba thẻ gói&quot;">​</a></h2><div class="wf"><div class="wf-screen"><div class="wf-browser-bar"><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-dot"></span><span class="wf-url">anphuc.vn/goi-cua-toi</span></div><div class="wf-body"><div class="wf-header"><span class="wf-logo">AnPhuc</span><span class="wf-nav"><span>Mua nhà</span><span>Đấu giá</span><span class="active">Bảng gói</span><span>Hướng dẫn</span></span><span class="wf-header-actions"><span class="wf-bell">🔔<span class="count">2</span></span><span class="wf-avatar">TV</span></span></div><div class="wf-container"><div class="wf-breadcrumb">Tài khoản › <b>Gói của tôi</b></div><span class="wf-title lg">Gói của tôi</span><div class="wf-card" style="border-width:2px;border-color:var(--wf-accent);"><div class="pad wf-col" style="gap:12px;"><div class="wf-row between middle wrap"><div class="wf-row middle wrap" style="gap:8px;"><span class="wf-badge wf-vip">VIP</span><span class="wf-title">VIP_STANDARD</span><span class="wf-badge ok">ACTIVE</span></div><span class="wf-small">Đăng ký <span class="wf-trace">sub_01J9ZK4C6D</span></span></div><div class="wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-text">Hạn mức tin đăng</span><span class="wf-strong">3 / 10 tin</span></div><div style="height:10px;border:1px solid var(--wf-line-strong);border-radius:5px;background:var(--wf-fill);overflow:hidden;"><div style="width:30%;height:100%;background:var(--wf-ink-soft);"></div></div><span class="wf-small wf-muted">Còn 7 tin trong chu kỳ này <span class="wf-callout">1</span></span></div><div class="wf-row wrap" style="gap:16px;"><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Bắt đầu</span><span class="wf-small">10/10/2026 14:32</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Hết hạn (GMT+7)</span><span class="wf-small wf-strong">09/11/2026 14:32</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Còn lại</span><span class="wf-sla ok">21 ngày</span></div><div class="wf-col" style="gap:2px;"><span class="wf-small wf-muted">Đã trả</span><span class="wf-small">500.000 ₫ / 30 ngày</span></div></div><div class="wf-row wrap" style="gap:8px;"><span class="wf-btn primary">Gia hạn thêm 30 ngày — 500.000 ₫ <span class="wf-callout">2</span></span><span class="wf-btn ghost">Đổi sang VIP_PRO</span><span class="wf-btn ghost">Đăng tin mới → SC-22</span></div><div class="wf-note" style="margin:0;">Quyền lợi đang có: badge <b>VIP</b> trên tin · tin được xếp <b>trước</b> trong danh sách nổi bật (VIP trước, rồi mới nhất) · hạn mức 10 tin. <span class="wf-callout">3</span></div></div></div><span class="wf-title">Bảng gói</span><div class="wf-grid cols-3"><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-badge muted">FREE</span><span class="wf-title">Miễn phí</span><span class="wf-money lg">0 ₫</span><span class="wf-small wf-muted">không giới hạn thời gian</span><div class="wf-col" style="gap:4px;"><span class="wf-small">✓ 2 tin đăng</span><span class="wf-small wf-muted">✗ Không badge VIP</span><span class="wf-small wf-muted">✗ Không ưu tiên hiển thị</span></div><span class="wf-btn disabled block">Gói hiện tại của bạn (dự phòng)</span></div></div><div class="wf-card" style="border-width:2px;border-color:var(--wf-accent);"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><span class="wf-badge wf-vip">VIP</span><span class="wf-small wf-accent">ĐANG DÙNG</span></div><span class="wf-title">VIP_STANDARD</span><span class="wf-money lg">500.000 ₫</span><span class="wf-small wf-muted">30 ngày</span><div class="wf-col" style="gap:4px;"><span class="wf-small">✓ 10 tin đăng</span><span class="wf-small">✓ Badge VIP trên tin</span><span class="wf-small">✓ Ưu tiên hiển thị</span></div><span class="wf-btn primary block">Gia hạn — cộng dồn 30 ngày</span></div></div><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-badge wf-vip">VIP</span><span class="wf-title">VIP_PRO</span><span class="wf-money lg">1.500.000 ₫</span><span class="wf-small wf-muted">30 ngày</span><div class="wf-col" style="gap:4px;"><span class="wf-small">✓ 50 tin đăng</span><span class="wf-small">✓ Badge VIP trên tin</span><span class="wf-small">✓ Ưu tiên hiển thị</span><span class="wf-small wf-muted">Rẻ hơn khi đăng trên 17 tin</span></div><span class="wf-btn block">Đổi sang gói này <span class="wf-callout danger">4</span></span></div></div></div><span class="wf-small wf-muted">Giá và quyền lợi lấy từ <code>GET /packages</code> (public), không hard-code ở FE. <span class="wf-callout">5</span></span></div><div class="wf-footer"><span>AnPhucRealEstate — sàn NOXH được vận hành bởi An Phuc</span><span>Quy chế đấu giá</span><span>CSKH 1900-xxx</span></div></div></div></div><div class="wf-legend"><div class="t">Chú thích hành vi (trace: docs/02 FR-PKG-01..04 · docs/08 BR-PKG-01..06 · docs/03 UC-10)</div><ol><li><span class="num">1</span><span>Thanh hạn mức + số &quot;3 / 10&quot; là thông tin quan trọng nhất màn — đặt ngay trong card gói hiện tại, không giấu trong tab. Khi ≥ 80% hạn mức thì đổi sắc thái warn; khi chạm hạn mức thì hiện dòng &quot;Đã dùng hết 10/10 tin&quot; + CTA nâng cấp (khớp message 422 ở SC-22). <span class="ref">BR-PKG-02</span> <span class="ref">FR-HS-10</span></span></li><li><span class="num">2</span><span>Nút gia hạn ghi rõ <b>&quot;cộng dồn 30 ngày&quot;</b> vì đây là điểm dễ hiểu lầm: hạn mới = 09/12/2026 14:32, không phải tính lại từ lúc bấm. <span class="ref">BR-PKG-03</span> <span class="ref">FR-PKG-02</span></span></li><li><span class="num">3</span><span>Quyền lợi dịch từ <code>entitlements</code>: <code>listingLimit</code> → số tin, <code>featuredBadge</code> → badge VIP, <code>prioritySort</code> → ưu tiên hiển thị. Ưu tiên là <b>quy tắc tĩnh</b> (VIP trước rồi newest) — không được viết &quot;AI đề xuất&quot;/&quot;tin của bạn sẽ được đẩy lên đầu&quot; vì không đúng. <span class="ref">BR-PKG-06</span> <span class="ref">FR-PKG-01</span></span></li><li><span class="num">4</span><span>Đổi gói khác packageCode là hành động <b>thiệt tiền</b> (mất 21 ngày còn lại) → bắt buộc qua dialog xác nhận ở mục 3, không checkout thẳng. Nút để dạng thường, không primary, để không dẫn người dùng vào lựa chọn tốn kém nhất. <span class="ref">BR-PKG-03</span> <span class="ref">UC-10 MF-1</span></span></li><li><span class="num">5</span><span>Màn này không có bảng so sánh &quot;tiết kiệm X%&quot; tự bịa; chỉ nêu giá, số ngày, số tin, quyền lợi đúng API. Giá đang chờ chốt OQ-8 nên FE phải đọc động. <span class="ref">BR-PKG-01</span></span></li></ol></div><h2 id="_2-cach-he-thong-đem-han-muc-minh-bach-cho-user" tabindex="-1">2. Cách hệ thống đếm hạn mức (minh bạch cho user) <a class="header-anchor" href="#_2-cach-he-thong-đem-han-muc-minh-bach-cho-user" aria-label="Permalink to &quot;2. Cách hệ thống đếm hạn mức (minh bạch cho user)&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">THẺ &quot;3/10 TIN ĐƯỢC TÍNH NHƯ SAU&quot;</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><span class="wf-small wf-strong">TIN ĐANG TÍNH VÀO HẠN MỨC</span><table class="wf-table"><thead><tr><th>Tin</th><th>Trạng thái</th><th>Tính quota?</th></tr></thead><tbody><tr><td>CT2-A18.05 — NOXH HP-380</td><td><span class="wf-badge ok">LISTED</span></td><td>Có</td></tr><tr><td>CT1-B07.02 — NOXH HP-380</td><td><span class="wf-badge ok">LISTED</span></td><td>Có</td></tr><tr><td>HH2-A03.11 — NOXH AQ-120</td><td><span class="wf-badge warn">RESERVED</span></td><td>Có</td></tr><tr><td>CT2-A20.08 — NOXH HP-380</td><td><span class="wf-badge muted">DRAFT</span></td><td>Không (chưa gửi duyệt)</td></tr><tr><td>CT3-C01.04 — NOXH HP-380</td><td><span class="wf-badge danger">REJECTED</span></td><td>Không</td></tr></tbody></table><span class="wf-small wf-muted">Tin đã bán (SOLD) vẫn tính nếu bán trong 30 ngày gần nhất. <span class="wf-callout">6</span></span></div></div></div><div class="wf-col"><span class="wf-state-label">CÂU HỎI USER HAY HỎI — TRẢ LỜI NGAY TRÊN MÀN</span><div class="wf-col" style="gap:8px;"><div class="wf-card flat"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Hết hạn gói thì tin đang đăng có bị gỡ không?</span><span class="wf-small"><b>Không.</b> Tin đã sống vẫn sống; hệ thống chỉ chặn <b>lúc bạn gửi tin mới</b> nếu vượt hạn mức của gói đang có. <span class="wf-callout">7</span></span></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Badge VIP trên tin cũ có mất không?</span><span class="wf-small">Có — biến mất ở lần đọc kế tiếp sau khi gói chuyển EXPIRED (job chạy mỗi giờ, nên có thể trễ tối đa ~1 giờ). <span class="ref">BR-PKG-05</span></span></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Có hoàn tiền / hủy giữa chu kỳ được không?</span><span class="wf-small">Bản hiện tại <b>không</b> hoàn, không hủy giữa chu kỳ. Ghi rõ trước khi thu tiền, không để user phát hiện sau. <span class="ref">BR-PKG-04</span> <span class="ref">FR-PKG-04</span></span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">6</span><span>Quy tắc đếm: tin có state ∈ {LISTED, RESERVED} hoặc SOLD trong 30 ngày gần nhất. DRAFT/IN_REVIEW/REJECTED/WITHDRAWN không tính. Bảng này giúp user tự lý giải vì sao bị chặn ở SC-22 thay vì phải gọi CS. <span class="ref">BR-PKG-02</span></span></li><li><span class="num">7</span><span>Đây là cam kết nghiệp vụ quan trọng nhất của nhóm gói: <b>enforce lúc submit, không cắt tin đang sống</b>. UI phải nói đúng như vậy, tránh câu mập mờ &quot;tin có thể bị ẩn&quot;. <span class="ref">BR-PKG-02</span></span></li></ol></div><h2 id="_3-dialog-xac-nhan-đoi-goi-mat-phan-con-lai-vs-gia-han-cung-goi" tabindex="-1">3. Dialog xác nhận đổi gói (mất phần còn lại) vs gia hạn cùng gói <a class="header-anchor" href="#_3-dialog-xac-nhan-đoi-goi-mat-phan-con-lai-vs-gia-han-cung-goi" aria-label="Permalink to &quot;3. Dialog xác nhận đổi gói (mất phần còn lại) vs gia hạn cùng gói&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">A — ĐỔI GÓI: CẢNH BÁO TRƯỚC THANH TOÁN</span><div class="wf-modal-overlay"><div class="wf-modal"><div class="head"><span class="wf-title">Đổi sang VIP_PRO</span><span class="wf-btn ghost sm">Đóng</span></div><div class="wf-col" style="gap:10px;"><div class="wf-note" style="margin:0;border-color:var(--wf-warn);">Bạn đang còn <b>21 ngày</b> VIP_STANDARD (đã trả 500.000 ₫ cho chu kỳ 30 ngày). Đổi gói ngay bây giờ: gói cũ kết thúc tức thì, <b>phần còn lại không được hoàn và không quy đổi</b>. <span class="wf-callout danger">8</span></div><div class="wf-row between"><span class="wf-text">Mất (21 ngày VIP_STANDARD còn lại)</span><span class="wf-money wf-danger-text">−350.000 ₫ giá trị</span></div><div class="wf-row between"><span class="wf-text">Thanh toán VIP_PRO 30 ngày</span><span class="wf-money">1.500.000 ₫</span></div><div class="wf-row between" style="border-top:2px solid var(--wf-ink);padding-top:8px;"><span class="wf-strong">Trả bây giờ</span><span class="wf-money lg">1.500.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Hạn mức sau khi đổi</span><span class="wf-strong">3 / 50 tin</span></div><div class="wf-row between"><span class="wf-text">Hết hạn mới</span><span>18/11/2026 14:32 (GMT+7)</span></div><div class="wf-row middle" style="gap:8px;"><span class="wf-checkbox"></span><span class="wf-small">Tôi hiểu phần còn lại của gói cũ sẽ mất và không được hoàn</span></div><span class="wf-btn disabled block">XÁC NHẬN &amp; THANH TOÁN 1.500.000 ₫</span><span class="wf-small wf-center">Nút chỉ mở khi tick ô trên — chống bấm theo quán tính.</span><span class="wf-btn ghost block sm">Để sau — giữ VIP_STANDARD tới 09/11/2026</span></div></div></div></div><div class="wf-col"><span class="wf-state-label">B — GIA HẠN CÙNG GÓI: KHÔNG CẦN CẢNH BÁO MẤT MÁT</span><div class="wf-modal-overlay"><div class="wf-modal"><div class="head"><span class="wf-title">Gia hạn VIP_STANDARD</span><span class="wf-btn ghost sm">Đóng</span></div><div class="wf-col" style="gap:10px;"><div class="wf-row between"><span class="wf-text">Hết hạn hiện tại</span><span>09/11/2026 14:32</span></div><div class="wf-row between"><span class="wf-text">Cộng thêm</span><span>+30 ngày</span></div><div class="wf-row between" style="border-top:2px solid var(--wf-ink);padding-top:8px;"><span class="wf-strong">Hết hạn mới</span><span class="wf-strong">09/12/2026 14:32 (GMT+7)</span></div><div class="wf-row between"><span class="wf-text">Thanh toán</span><span class="wf-money lg">500.000 ₫</span></div><div class="wf-col" style="gap:4px;"><span class="wf-small wf-strong">KÊNH THANH TOÁN</span><div class="wf-row middle" style="gap:8px;"><span class="wf-radio checked"></span><span class="wf-small">VNPay (kích hoạt ngay)</span></div><div class="wf-row middle" style="gap:8px;"><span class="wf-radio"></span><span class="wf-small">Chuyển khoản thủ công (ADMIN đối soát ≤ 2 giờ làm việc)</span></div></div><span class="wf-btn primary block">THANH TOÁN 500.000 ₫</span><span class="wf-small wf-muted">Không hoàn, không hủy giữa chu kỳ — <span class="ref">BR-PKG-04</span></span></div></div></div><div class="wf-card flat" style="margin-top:10px;"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Sau khi bấm thanh toán</span><span class="wf-small">Nút loading disabled (gửi kèm <code>Idempotency-Key</code>) → chuyển sang VNPay → quay lại thì FE <b>poll <code>/users/me/subscriptions</code></b> cho tới khi ACTIVE, vì webhook có thể về trước redirect. Không hiện &quot;thành công&quot; chỉ dựa vào URL quay lại. <span class="ref">UC-10 EF-1</span> <span class="ref">docs/06 §1</span></span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">8</span><span>Con số &quot;−350.000 ₫ giá trị&quot; là cách diễn giải cho user (500.000 ₫ × 21/30), phải ghi chú đó là <b>giá trị quy đổi tham chiếu</b>, không phải khoản sẽ hoàn. Nếu PM thấy dễ gây hiểu nhầm thì bỏ dòng này, chỉ giữ &quot;21 ngày còn lại sẽ mất&quot;. Đây là điểm cần designer + PM chốt. <span class="ref">BR-PKG-03</span> <span class="ref">UC-10 MF-1</span></span></li><li><span class="num">9</span><span>Hai dialog phải <b>khác nhau rõ</b>: đổi gói = nền warn + tick bắt buộc + nút disabled; gia hạn = thông tin ngày tháng + nút primary ngay. Đừng dùng chung một modal với chữ khác nhau. <span class="ref">BR-PKG-03</span></span></li><li><span class="num">10</span><span>Thanh toán thất bại hoặc user hủy tại gateway → <code>intent FAILED</code>, <b>gói không đổi</b>, quay lại màn này vẫn thấy VIP_STANDARD như cũ + toast &quot;Thanh toán chưa hoàn tất — gói của bạn không thay đổi&quot;. <span class="ref">UC-10 AF-2</span></span></li></ol></div><h2 id="_4-bien-the-expired-free-va-lich-su-goi" tabindex="-1">4. Biến thể EXPIRED / FREE và lịch sử gói <a class="header-anchor" href="#_4-bien-the-expired-free-va-lich-su-goi" aria-label="Permalink to &quot;4. Biến thể EXPIRED / FREE và lịch sử gói&quot;">​</a></h2><div class="wf"><div class="wf-grid"><div class="wf-col"><span class="wf-state-label">EXPIRED — VỀ GÓI FREE</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><div class="wf-row middle wrap" style="gap:8px;"><span class="wf-badge muted">FREE</span><span class="wf-title">Miễn phí</span><span class="wf-badge danger">VIP_STANDARD ĐÃ HẾT HẠN</span></div><span class="wf-small">Gói VIP_STANDARD của bạn hết hạn lúc <b>09/11/2026 14:32 (GMT+7)</b>. Badge VIP trên tin đã được gỡ ở lần hiển thị kế tiếp.</span><div class="wf-col" style="gap:6px;"><div class="wf-row between"><span class="wf-text">Hạn mức hiện tại</span><span class="wf-strong">2 / 2 tin (đã dùng hết)</span></div><div style="height:10px;border:1px solid var(--wf-line-strong);border-radius:5px;background:var(--wf-fill);overflow:hidden;"><div style="width:100%;height:100%;background:var(--wf-danger);"></div></div></div><div class="wf-note" style="margin:0;">Tin bạn đang đăng <b>vẫn còn hiệu lực</b> — hết hạn gói không gỡ tin. Bạn chỉ không gửi được tin mới cho tới khi còn hạn mức. <span class="wf-callout">11</span></div><div class="wf-row wrap" style="gap:8px;"><span class="wf-btn primary">Mua lại VIP_STANDARD — 500.000 ₫</span><span class="wf-btn ghost">Xem 2 tin đang chiếm hạn mức</span></div><div class="wf-card flat"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">Bấm &quot;Đăng tin&quot; lúc này (422)</span><div class="wf-field-error">Bạn đã dùng 2/2 tin. Nâng cấp VIP để đăng thêm</div><span class="wf-small wf-muted">Message nguyên văn docs/06 §5 — hiện ở SC-22 và trong modal upsell dẫn về màn này.</span></div></div></div></div></div><div class="wf-col"><span class="wf-state-label">LỊCH SỬ GÓI — GET /users/me/subscriptions</span><div class="wf-card"><div class="pad wf-col" style="gap:8px;"><table class="wf-table"><thead><tr><th>Gói</th><th>Bắt đầu</th><th>Kết thúc</th><th>Trạng thái</th><th>Đã trả</th></tr></thead><tbody><tr><td>VIP_STANDARD</td><td>10/10/2026 14:32</td><td>09/11/2026 14:32</td><td><span class="wf-badge ok">ACTIVE</span></td><td>500.000 ₫</td></tr><tr><td>FREE</td><td>02/09/2026 10:05</td><td>—</td><td><span class="wf-badge muted">MẶC ĐỊNH</span></td><td>0 ₫</td></tr></tbody></table><span class="wf-small wf-muted">Trạng thái có thể gặp: <b>PENDING</b> (đã tạo, chờ webhook) · <b>ACTIVE</b> · <b>EXPIRED</b> (hết hạn) · <b>SUPERSEDED</b> (bị thay khi đổi gói). <span class="wf-callout">12</span></span><div class="wf-col" style="gap:4px;margin-top:4px;"><span class="wf-small wf-strong">PENDING trông thế nào</span><span class="wf-small">Card gói hiện banner info &quot;Đang chờ xác nhận thanh toán — gói chưa kích hoạt&quot;, kèm hạn TTL của intent và nút &quot;Đã thanh toán? Kiểm tra lại&quot;. Không hiện hạn mức mới khi còn PENDING.</span></div></div></div><div class="wf-card flat"><div class="pad wf-col" style="gap:4px;"><span class="wf-small wf-strong">KYC chưa đạt (403 KYC_REQUIRED)</span><div class="wf-field-error">Bạn cần xác minh danh tính (CCCD) trước khi thao tác này</div><span class="wf-small">Màn này vẫn xem được bảng gói, nhưng mọi nút mua đều thay bằng &quot;Xác minh danh tính → SC-21&quot;. Message nguyên văn docs/06 §5. <span class="ref">BR-KYC-08</span></span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">11</span><span>Biến thể EXPIRED phải <b>trấn an trước, upsell sau</b>: điều đầu tiên user lo là &quot;tin của tôi có bị gỡ không&quot;. Trả lời câu đó ở dòng note, rồi mới tới CTA mua lại. <span class="ref">BR-PKG-02</span> <span class="ref">BR-PKG-05</span></span></li><li><span class="num">12</span><span>Lịch sử là bằng chứng cho mọi tranh chấp tiền gói: mỗi dòng có ngày bắt đầu/kết thúc + số tiền + trạng thái. SUPERSEDED phải hiện rõ (không ẩn) để user hiểu vì sao mất phần còn lại. <span class="ref">FR-PKG-04</span> <span class="ref">BR-PKG-03</span></span></li><li><span class="num">13</span><span>Job hết hạn chạy mỗi giờ → UI không được khẳng định &quot;badge gỡ ngay lập tức&quot;; dùng chữ &quot;ở lần hiển thị kế tiếp&quot; cho đúng nghiệp vụ. <span class="ref">BR-PKG-05</span> <span class="ref">FR-PKG-03</span></span></li></ol></div><h2 id="_5-mobile-360px" tabindex="-1">5. Mobile 360px <a class="header-anchor" href="#_5-mobile-360px" aria-label="Permalink to &quot;5. Mobile 360px&quot;">​</a></h2><div class="wf"><div class="wf-row" style="justify-content:center;gap:20px;flex-wrap:wrap;"><div><span class="wf-state-label">MOBILE — GÓI HIỆN TẠI</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-container" style="padding:12px;"><div class="wf-title">Gói của tôi</div><div class="wf-card" style="border-width:2px;border-color:var(--wf-accent);margin-top:8px;"><div class="pad wf-col" style="gap:8px;"><div class="wf-row between middle"><div class="wf-row middle" style="gap:6px;"><span class="wf-badge wf-vip">VIP</span><span class="wf-strong">VIP_STANDARD</span></div><span class="wf-badge ok">ACTIVE</span></div><div class="wf-row between"><span class="wf-text">Hạn mức</span><span class="wf-strong">3 / 10 tin</span></div><div style="height:10px;border:1px solid var(--wf-line-strong);border-radius:5px;background:var(--wf-fill);overflow:hidden;"><div style="width:30%;height:100%;background:var(--wf-ink-soft);"></div></div><div class="wf-row between"><span class="wf-text">Hết hạn</span><span class="wf-small">09/11/2026 14:32</span></div><div class="wf-row between"><span class="wf-text">Còn lại</span><span class="wf-sla ok">21 ngày</span></div><span class="wf-small wf-muted">Badge VIP · ưu tiên hiển thị · 10 tin</span></div></div><div class="wf-title" style="margin-top:14px;">Bảng gói</div><div class="wf-card" style="margin-top:8px;"><div class="pad wf-col" style="gap:4px;"><div class="wf-row between middle"><span class="wf-strong">VIP_PRO — 50 tin</span><span class="wf-money">1.500.000 ₫</span></div><span class="wf-small wf-muted">30 ngày · badge VIP · ưu tiên hiển thị</span><span class="wf-btn sm block">Đổi sang gói này</span></div></div><div class="wf-card" style="margin-top:8px;border-color:var(--wf-accent);"><div class="pad wf-col" style="gap:4px;"><div class="wf-row between middle"><span class="wf-strong">VIP_STANDARD — 10 tin</span><span class="wf-money">500.000 ₫</span></div><span class="wf-small wf-accent">Đang dùng</span></div></div><div class="wf-card" style="margin-top:8px;"><div class="pad wf-col" style="gap:4px;"><div class="wf-row between middle"><span class="wf-strong">FREE — 2 tin</span><span class="wf-money">0 ₫</span></div><span class="wf-small wf-muted">Không badge · không ưu tiên</span></div></div></div><div class="wf-col" style="gap:6px;position:sticky;bottom:0;background:#fff;border-top:1px solid var(--wf-line);padding:10px 12px;"><span class="wf-btn primary block">GIA HẠN 30 NGÀY — 500.000 ₫</span></div></div></div><div><span class="wf-state-label">MOBILE — SHEET XÁC NHẬN ĐỔI GÓI</span><div class="wf-mobile"><div class="wf-mobile-bar"><span>9:41</span><span>▮▮▮ ⌁ ▰</span></div><div class="wf-header" style="padding:8px 12px;"><span class="wf-logo">AnPhuc</span><span class="wf-bell">🔔<span class="count">2</span></span></div><div class="wf-container" style="padding:12px;opacity:0.4;"><div class="wf-title">Gói của tôi</div><div class="wf-skeleton" style="margin-top:8px;"><div class="wf-lines"><span class="w-60"></span><span class="w-90"></span><span class="w-40"></span></div></div></div><div class="wf-drawer"><div class="wf-col" style="gap:8px;"><span class="wf-title">Đổi sang VIP_PRO</span><div class="wf-note" style="margin:0;border-color:var(--wf-warn);">Còn 21 ngày VIP_STANDARD — gói cũ kết thúc ngay, <b>không hoàn, không quy đổi</b>.</div><div class="wf-row between"><span class="wf-text">Trả bây giờ</span><span class="wf-money lg">1.500.000 ₫</span></div><div class="wf-row between"><span class="wf-text">Hạn mức mới</span><span class="wf-strong">3 / 50 tin</span></div><div class="wf-row middle" style="gap:8px;"><span class="wf-checkbox"></span><span class="wf-small">Tôi hiểu và đồng ý</span></div><span class="wf-btn disabled block">XÁC NHẬN &amp; THANH TOÁN</span><span class="wf-btn ghost block sm">Giữ gói hiện tại</span></div></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích mobile</div><ol><li><span class="num">M</span><span>Bảng gói xếp dọc thành card 1 cột (không carousel — carousel giấu gói FREE và gây cảm giác bị ép mua). CTA gia hạn sticky dưới đáy.</span></li><li><span class="num">M</span><span>Dialog đổi gói thành <code>wf-drawer</code> trượt đáy, vẫn giữ tick bắt buộc + nút disabled; không rút gọn cảnh báo mất tiền trên mobile.</span></li></ol></div><h2 id="_6-bon-trang-thai-nen-amp-loi-bien" tabindex="-1">6. Bốn trạng thái nền &amp; lỗi biên <a class="header-anchor" href="#_6-bon-trang-thai-nen-amp-loi-bien" aria-label="Permalink to &quot;6. Bốn trạng thái nền &amp;amp; lỗi biên&quot;">​</a></h2><div class="wf"><div class="wf-grid cols-4"><div class="wf-col"><span class="wf-state-label">LOADING</span><div class="wf-col" style="gap:8px;"><div class="wf-skeleton"><div class="wf-lines"><span class="w-40"></span><span class="w-90"></span><span class="w-60"></span></div></div><div class="wf-skeleton"><div class="wf-lines"><span class="w-75"></span><span class="w-50"></span></div></div><span class="wf-small">Skeleton card gói + 3 thẻ; <b>không hiện giá placeholder</b> (dễ chụp màn hình nhầm thành giá thật).</span></div></div><div class="wf-col"><span class="wf-state-label">EMPTY</span><div class="wf-empty"><span class="icon">◈</span><span class="wf-title">Bạn đang ở gói Miễn phí</span><div class="wf-text">Chưa có lịch sử mua gói nào. 2 tin đăng đang chờ bạn dùng.</div><span class="wf-btn primary">Xem bảng gói</span></div></div><div class="wf-col"><span class="wf-state-label">ERROR</span><div class="wf-error-box"><span class="wf-title">Không tải được gói của bạn</span><div class="wf-text" style="margin:6px 0;">Gói hiện tại vẫn hoạt động bình thường — chỉ màn hình này lỗi. Đừng thanh toán lại lần nữa.</div><span class="wf-btn block">Thử lại</span><span class="wf-trace">traceId a1b2c3 — đọc mã này khi gọi CS 1900-xxx</span></div></div><div class="wf-col"><span class="wf-state-label">DATA</span><div class="wf-card"><div class="pad wf-col" style="gap:6px;"><span class="wf-small wf-strong">Biến thể phải có</span><span class="wf-small">FREE (mặc định) · VIP_STANDARD ACTIVE · VIP_PRO ACTIVE · PENDING chờ webhook · EXPIRED về FREE · có dòng SUPERSEDED trong lịch sử · hạn mức đầy (2/2, 10/10) · KYC chưa đạt.</span></div></div></div></div></div><div class="wf-legend"><div class="t">Chú thích</div><ol><li><span class="num">14</span><span>Quy tắc 4 trạng thái + các biến thể nghiệp vụ riêng của màn tiền gói. Gateway down → hiện kênh chuyển khoản thủ công với nội dung <code>ANPHUC &lt;paymentId&gt;</code> và ghi rõ gói chỉ kích hoạt sau khi ADMIN đối soát (≤ 2 giờ làm việc). <span class="ref">docs/05 §1.4</span> <span class="ref">UC-10 EF-2</span> <span class="ref">FR-PAY-03</span></span></li></ol></div><h2 id="_7-checklist-designer-khi-dung-figma-cho-sc-26" tabindex="-1">7. Checklist designer khi dựng Figma cho SC-26 <a class="header-anchor" href="#_7-checklist-designer-khi-dung-figma-cho-sc-26" aria-label="Permalink to &quot;7. Checklist designer khi dựng Figma cho SC-26&quot;">​</a></h2><ul><li>[ ] Đủ layout: desktop (card gói + bảng gói 3 cột) / tablet 768 (bảng gói 2 cột) / mobile 360 (xếp dọc, CTA sticky)</li><li>[ ] Card gói hiện tại: tên gói + badge VIP + trạng thái + hạn mức <code>X/limit</code> + thanh usage + startsAt/endsAt (GMT+7) + còn N ngày + đã trả</li><li>[ ] Thanh usage 3 sắc thái: thường / ≥80% warn / chạm hạn mức danger kèm CTA nâng cấp</li><li>[ ] Ba thẻ gói đúng <code>GET /packages</code>: FREE 0 ₫·2 tin / VIP_STANDARD 500.000 ₫·30 ngày·10 tin / VIP_PRO 1.500.000 ₫·30 ngày·50 tin — quyền lợi dịch từ <code>listingLimit</code>, <code>featuredBadge</code>, <code>prioritySort</code></li><li>[ ] Đánh dấu gói đang dùng trên thẻ (không chỉ ở card trên) và disable/đổi CTA tương ứng</li><li>[ ] Dialog đổi gói: cảnh báo mất phần còn lại + checkbox bắt buộc + nút disabled tới khi tick + ngày hết hạn mới + hạn mức mới</li><li>[ ] Dialog gia hạn: ngày cũ → +30 ngày → ngày mới, kênh VNPay / chuyển khoản thủ công</li><li>[ ] Trạng thái PENDING (chờ webhook): gói chưa kích hoạt, không hiện hạn mức mới</li><li>[ ] Biến thể EXPIRED: về FREE, badge VIP đã gỡ, trấn an &quot;tin không bị gỡ&quot;, CTA mua lại</li><li>[ ] Bảng minh bạch cách đếm quota (LISTED/RESERVED/SOLD 30 ngày tính; DRAFT/REJECTED không)</li><li>[ ] Bảng lịch sử gói với đủ 4 trạng thái PENDING/ACTIVE/EXPIRED/SUPERSEDED</li><li>[ ] Gate KYC 403 với message nguyên văn docs/06 §5 + CTA sang SC-21</li><li>[ ] 4 trạng thái nền: skeleton (không giá giả) / empty (đang FREE) / error (trấn an + traceId) / data</li><li>[ ] Không copy bán hàng sai sự thật: không đếm ngược giả, không &quot;chỉ còn X suất&quot;, không nói &quot;AI đẩy tin&quot;</li><li>[ ] Không emoji làm icon production (✓/✗/🔔 trong wireframe chỉ là placeholder vị trí)</li><li>[ ] Accessibility: thanh usage có text tương đương (đã có <code>3/10</code>), checkbox đổi gói có label thật, contrast AA cho badge VIP, focus ring khi mở/đóng dialog</li></ul><div class="info custom-block"><p class="custom-block-title">Góp ý màn này?</p><p>Comment ngay bên dưới — ghi rõ khu vực (số callout) và đề xuất. Thay đổi nghiệp vụ cần PM duyệt trên docs/08 trước.</p></div>',24)])])}const w=a(t,[["render",c]]);export{r as __pageData,w as default};
